                if (!siz) goto shortbuf;
                sysex_len = (sysex_len << 7) + (*event_data & 0x7F);
                event_data++;
                ret_cnt++;
                if (--siz < sysex_len) goto shortbuf;
                if (!sysex_len) break; /* bad file? */

