   ```c
   if (op->frame_rate_info_flag) 
       fprintf(trace, " avgFrameRate=\"%u\" constantFrameRate=\"%u\"", op->avgFrameRate, op->constantFrameRate);
   if (op->bit_rate_info_flag) 
